    final private String toSnapshot;
    final private byte[] startPath;
    final private long startIndex;

    /**
     * Creates a snapshot diff listing executor.
     */
    public FSSnapshotDiffReportListing(String path, String fromSnapshot,
        String toSnapshot, String startPath, long startIndex) {
      this.path = new Path(path);
      this.fromSnapshot = fromSnapshot;
      this.toSnapshot = toSnapshot;
      this.startPath = DFSUtilClient.string2Bytes(startPath);
      this.startIndex = startIndex;
