    @Override
    public String execute(FileSystem fs) throws IOException {
      SnapshotDiffReportListing diffReportListing = null;
      if (fs instanceof DistributedFileSystem) {
        DistributedFileSystem dfs = (DistributedFileSystem) fs;
        diffReportListing = dfs.getSnapshotDiffReportListing(path,
            fromSnapshot, toSnapshot, startPath, startIndex);
      } else {
        throw new UnsupportedOperationException("Snapshot diff listing is"
            + "not supported for HttpFs on non-HDFS file systems");
      }
      return JsonUtil.toJsonString(diffReportListing);
    }
  }
