415	+  private void testGetSnapshotDiffListing() throws Exception {
416	+    if (!this.isLocalFS()) {
417	+      // Create a directory with snapshot allowed
418	+      Path path = new Path("/tmp/tmp-snap-test");
419	+      createSnapshotTestsPreconditions(path);
420	+      // Get the FileSystem instance that's being tested
421	+      FileSystem fs = this.getHttpFSFileSystem();
422	+      // Check FileStatus
423	+      Assert.assertTrue(fs.getFileStatus(path).isSnapshotEnabled());
424	+      // Create a file and take a snapshot
425	+      Path file1 = new Path(path, "file1");
426	+      testCreate(file1, false);
427	+      fs.createSnapshot(path, "snap1");
428	+      // Create another file and take a snapshot
429	+      Path file2 = new Path(path, "file2");
430	+      testCreate(file2, false);
431	+      fs.createSnapshot(path, "snap2");
432	+      // Get snapshot diff listing
433	+      try {
434	+        SnapshotDiffReportListing diffReportListing = null;
435	+        byte[] emptyBytes = new byte[] {};
436	+        if (fs instanceof HttpFSFileSystem) {
437	+          HttpFSFileSystem httpFS = (HttpFSFileSystem) fs;
438	+          diffReportListing =
439	+              httpFS.getSnapshotDiffReportListing(path, "snap1", "snap2", emptyBytes, -1);
440	+        } else if (fs instanceof WebHdfsFileSystem) {
441	+          WebHdfsFileSystem webHdfsFileSystem = (WebHdfsFileSystem) fs;
442	+          diffReportListing = webHdfsFileSystem
443	+              .getSnapshotDiffReportListing(path.toUri().getPath(), "snap1", "snap2", emptyBytes,
444	+                  -1);
445	+        } else {
446	+          Assert.fail(fs.getClass().getSimpleName() + " doesn't support getSnapshotDiff");
447	+        }
448	+        // Verify result with DFS
449	+        DistributedFileSystem dfs =
450	+            (DistributedFileSystem) FileSystem.get(path.toUri(), this.getProxiedFSConf());
451	+        SnapshotDiffReportListing dfsDiffReportListing =
452	+            dfs.getSnapshotDiffReportListing(path, "snap1", "snap2",
453	+                DFSUtil.bytes2String(emptyBytes), -1);
454	+        assertHttpFsReportListingWithDfsClient(diffReportListing, dfsDiffReportListing);
455	+      } finally {
456	+        // Cleanup
457	+        fs.deleteSnapshot(path, "snap2");
458	+        fs.deleteSnapshot(path, "snap1");
459	+        fs.delete(path, true);
460	+      }
461	+    }
